import { computed, ref } from 'vue'
import { toast } from 'frappe-ui'

import { apiErrorMessage, hasApiError } from '@/api/client'
import { gitApi } from '@/api/git'
import type { GitConnection } from '@/types/git'
import { errorMessage } from '@/utils/error'

export const useGithubConnection = () => {
  const loading = ref(true)
  const connecting = ref(false)
  const verifying = ref(false)
  const redirecting = ref(false)
  const error = ref('')
  const status = ref<GitConnection | null>(null)
  const username = ref('')
  const token = ref('')

  const viaCentral = computed(() => status.value?.auth_type === 'github_app')
  const centralAvailable = computed(() => Boolean(status.value?.central?.available))
  const centralAccounts = computed(() => status.value?.central?.connections ?? [])
  const connected = computed(() =>
    Boolean(status.value?.connected && (viaCentral.value || status.value?.is_token_valid)),
  )
  const tokenHelpUrl = computed(
    () =>
      status.value?.providers?.github ||
      'https://github.com/settings/tokens/new?scopes=repo&description=Bench+CLI',
  )

  const load = async () => {
    loading.value = true

    try {
      status.value = await gitApi.status()

      if (status.value?.username && !viaCentral.value) username.value = status.value.username
    } finally {
      loading.value = false
    }
  }

  const connect = async () => {
    if (!token.value.trim()) {
      error.value = 'Paste a personal access token to connect.'

      return false
    }

    connecting.value = true
    error.value = ''

    try {
      const result = await gitApi.connect('github', token.value.trim(), username.value.trim())

      if (hasApiError(result)) {
        error.value = apiErrorMessage(result, 'Could not verify token.')

        return false
      }

      token.value = ''
      status.value = { ...result, central: status.value?.central }
      toast.success(`Connected as ${result.username}`)

      return true
    } catch (e) {
      error.value = errorMessage(e, 'Could not verify token.')

      return false
    } finally {
      connecting.value = false
    }
  }

  const connectViaCentral = async (returnUrl: string) => {
    redirecting.value = true
    error.value = ''

    try {
      const result = await gitApi.connectViaCentral(returnUrl)

      if (hasApiError(result))
        throw new Error(apiErrorMessage(result, 'Could not reach Frappe Cloud.'))

      window.location.assign(result.url)
    } catch (e) {
      error.value = errorMessage(e, 'Could not reach Frappe Cloud.')
      redirecting.value = false
    }
  }

  const verifyConnection = async () => {
    verifying.value = true

    try {
      const result = await gitApi.repos()

      if (Array.isArray(result)) toast.success('GitHub connection is working')
      else toast.error(apiErrorMessage(result, 'GitHub connection failed'))
    } catch (e) {
      toast.error(errorMessage(e, 'GitHub connection failed'))
    } finally {
      await load()
      verifying.value = false
    }
  }

  const disconnect = async () => {
    const response = await gitApi.disconnect()

    if (!response.ok) {
      toast.error(apiErrorMessage(await response.json(), 'Could not disconnect GitHub.'))

      return
    }

    username.value = ''
    await load()
  }

  return {
    loading,
    connecting,
    verifying,
    redirecting,
    error,
    status,
    username,
    token,
    connected,
    viaCentral,
    centralAvailable,
    centralAccounts,
    tokenHelpUrl,
    load,
    connect,
    connectViaCentral,
    verifyConnection,
    disconnect,
  }
}

import { computed, ref, watch } from 'vue'
import { toast } from 'frappe-ui'

import { apiErrorMessage, hasApiError } from '@/api/client'
import { settingsApi } from '@/api/settings'
import type { S3ProviderOption } from '@/types/settings'
import { errorMessage } from '@/utils/error'

export const useObjectStorage = () => {
  const loading = ref(true)
  const saving = ref(false)
  const disconnecting = ref(false)
  const error = ref('')
  const accessKey = ref('')
  const secretKey = ref('')
  const bucket = ref('')
  const provider = ref('')
  const region = ref('')
  const endpointUrl = ref('')
  const secretKeySet = ref(false)
  const providers = ref<S3ProviderOption[]>([])
  const loadingRegions = ref(false)

  const connected = computed(() => Boolean(accessKey.value && bucket.value && secretKeySet.value))
  const providerLabel = computed(
    () => providers.value.find((p) => p.value === provider.value)?.label || provider.value,
  )
  const providerOptions = computed(() =>
    providers.value.map((p) => ({ label: p.label, value: p.value })),
  )
  const regionOptions = computed(
    () =>
      providers.value
        .find((p) => p.value === provider.value)
        ?.regions.map((r) => ({ label: r, value: r })) || [],
  )

  const loadFrappeRegions = async () => {
    const frappe = providers.value.find((p) => p.value === 'frappe')

    if (!frappe) return

    loadingRegions.value = true

    try {
      const regions = await settingsApi.frappeStorageRegions()

      if (hasApiError(regions)) {
        error.value = apiErrorMessage(
          regions,
          'Could not read Frappe storage regions from Central.',
        )

        return
      }

      frappe.regions = regions
    } catch (e) {
      error.value = errorMessage(e, 'Could not read Frappe storage regions from Central.')
    } finally {
      loadingRegions.value = false
    }
  }

  watch([provider, providers], async ([current], [previous]) => {
    if (previous && current !== previous) {
      endpointUrl.value = ''
    }

    if (current === 'frappe') {
      await loadFrappeRegions()
    }

    if (!regionOptions.value.some((o) => o.value === region.value)) {
      region.value = regionOptions.value[0]?.value || ''
    }
  })

  const canSave = computed(
    () =>
      Boolean(accessKey.value.trim()) &&
      Boolean(bucket.value.trim()) &&
      Boolean(provider.value) &&
      Boolean(region.value) &&
      (secretKeySet.value || Boolean(secretKey.value.trim())),
  )

  const load = async () => {
    loading.value = true

    try {
      const data = await settingsApi.get()
      const s3 = data.s3 || {}

      providers.value = data.s3_providers || []
      accessKey.value = s3.access_key || ''
      bucket.value = s3.bucket || ''
      provider.value = s3.provider || providers.value[0]?.value || ''
      region.value = s3.region || ''
      endpointUrl.value = s3.endpoint_url || ''
      secretKeySet.value = !!s3.secret_key_set
    } catch (e) {
      error.value = errorMessage(e, 'Could not load settings.')
    } finally {
      loading.value = false
    }
  }

  const save = async () => {
    saving.value = true
    error.value = ''

    try {
      await settingsApi.update({
        s3: {
          access_key: accessKey.value.trim(),
          secret_key: secretKey.value.trim(),
          bucket: bucket.value.trim(),
          provider: provider.value,
          region: region.value,
          endpoint_url: endpointUrl.value.trim(),
        },
      })

      secretKey.value = ''
      toast.success('Object storage settings saved')
      await load()

      return true
    } catch (e) {
      error.value = errorMessage(e, 'Could not save object storage settings.')

      return false
    } finally {
      saving.value = false
    }
  }

  const disconnect = async () => {
    disconnecting.value = true

    try {
      await settingsApi.update({ s3: { disconnect: true } })

      accessKey.value = ''
      secretKey.value = ''
      bucket.value = ''
      provider.value = providers.value[0]?.value || ''
      region.value = ''
      endpointUrl.value = ''
      secretKeySet.value = false

      toast.success('Object storage disconnected')
    } catch (e) {
      toast.error(errorMessage(e, 'Could not disconnect object storage.'))
    } finally {
      disconnecting.value = false
    }
  }

  return {
    loading,
    saving,
    disconnecting,
    error,
    accessKey,
    secretKey,
    bucket,
    provider,
    region,
    endpointUrl,
    secretKeySet,
    providers,
    loadingRegions,
    connected,
    providerLabel,
    providerOptions,
    regionOptions,
    canSave,
    load,
    save,
    disconnect,
  }
}

import { computed, ref, watch } from 'vue'

import { appsApi } from '@/api/apps'
import { apiErrorMessage } from '@/api/client'
import { sitesApi } from '@/api/sites'
import { useAppRegistry } from '@/composables/apps/useAppRegistry'
import type { AppInfo } from '@/types/apps'
import { errorMessage } from '@/utils/error'
import { buildSiteAppChoices } from '@/utils/siteApps'

const validate = (name: string) => {
  if (!name) return 'Site name is required.'
  if (!/^[a-zA-Z0-9][a-zA-Z0-9\-.]*[a-zA-Z0-9]$|^[a-zA-Z0-9]$/.test(name))
    return 'Site name must be a valid hostname.'
  return null
}

export const useNewSite = () => {
  const { registry, load: loadRegistry } = useAppRegistry()
  const benchApps = ref<AppInfo[]>([])

  const name = ref('')
  const prefix = ref('')
  const wildcardDomains = ref<string[]>([])
  const suffix = ref('')
  const selectedApps = ref<string[]>([])
  const appSearch = ref('')
  const loading = ref(false)
  const creating = ref(false)
  const error = ref('')

  const hasSingleDomain = computed(() => wildcardDomains.value.length === 1)
  const nameError = computed(() => validate(name.value.trim()))
  const availableApps = computed(() => buildSiteAppChoices(registry.value, benchApps.value))
  const frappe = computed(() => benchApps.value.find((app) => app.name === 'frappe'))
  const filteredApps = computed(() => {
    const query = appSearch.value.trim().toLowerCase()

    if (!query) return availableApps.value

    return availableApps.value.filter((app) =>
      [app.title, app.name].some((text) => text?.toLowerCase().includes(query)),
    )
  })

  watch([prefix, suffix], () => {
    name.value =
      wildcardDomains.value.length && prefix.value ? `${prefix.value.trim()}${suffix.value}` : ''
  })

  const loadBenchApps = async () => {
    try {
      benchApps.value = await appsApi.installed()
    } catch {
      benchApps.value = []
    }
  }

  const loadWildcardDomains = async () => {
    try {
      const { domains } = await sitesApi.domains.wildcardList()

      wildcardDomains.value = domains || []
      suffix.value = wildcardDomains.value[0] || ''
    } catch {
      wildcardDomains.value = []
    }
  }

  const reset = async () => {
    name.value = ''
    prefix.value = ''
    error.value = ''
    selectedApps.value = []
    appSearch.value = ''
    loading.value = true

    await Promise.all([loadWildcardDomains(), loadRegistry(), loadBenchApps()])

    loading.value = false
  }

  const toggleApp = (app: string) => {
    const index = selectedApps.value.indexOf(app)

    if (index === -1) selectedApps.value.push(app)
    else selectedApps.value.splice(index, 1)
  }

  const create = async () => {
    const siteName = name.value.trim()
    const validationError = validate(siteName)

    if (validationError) {
      error.value = validationError

      return null
    }

    creating.value = true
    error.value = ''

    try {
      const result = await sitesApi.create({ name: siteName, apps: selectedApps.value })

      if (result.task_id) return result.task_id

      error.value = apiErrorMessage(result, 'Could not create site.')
    } catch (caught) {
      error.value = errorMessage(caught, 'Could not create site.')
    } finally {
      creating.value = false
    }

    return null
  }

  return {
    name,
    prefix,
    wildcardDomains,
    suffix,
    selectedApps,
    appSearch,
    loading,
    creating,
    error,
    hasSingleDomain,
    nameError,
    availableApps,
    filteredApps,
    frappe,
    reset,
    toggleApp,
    create,
  }
}

