:root {
  /* Strong UI easing curves (built-in CSS easings are too weak) */
  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
}

body {
  @apply bg-surface-base text-ink-gray-9 text-base;
}

/* Alpha gray: selection lands on any surface, and it flips polarity in dark
   mode. Background only, so text keeps its ink color. */
::selection {
  background-color: var(--surface-alpha-gray-4);
}

.mobile-sidebar [data-slot="sidebar-item"] .text-sm {
  @apply !text-[16px];
}

.mobile-sidebar [data-slot="sidebar-item"] {
  @apply !h-auto !py-2.5;
}

[data-slot="chart-legend"] {
  @apply flex-nowrap justify-start overflow-x-auto;
}

/* A hovered row reads as one block, so the rules touching it fade. Goes on the
   rows' parent; rows qualify by carrying a hover background, not by tag. First
   pair covers `divide-y`, second covers rows wrapping a bordered body.
   `!important` breaks a specificity tie with Tailwind's divide rule. */
.hover-merges-dividers > [class*='hover:bg-']:hover,
.hover-merges-dividers > [class*='hover:bg-']:hover + * {
  border-top-color: transparent !important;
}

.hover-merges-dividers > [class*='hover:bg-']:hover > *,
.hover-merges-dividers > *:has(+ [class*='hover:bg-']:hover) > * {
  border-bottom-color: transparent;
}

/* Reduced motion: keep transitions near-instant, drop movement */
@media (prefers-reduced-motion: reduce) {
  *,
  ::before,
  ::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* Smart scrollbars: thin, rounded, hidden until the pointer is inside the
   scroll area — the macOS overlay feel, brought to Windows/Linux too. Colors
   use espresso tokens so they follow light/dark automatically. */
* {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}

*:hover {
  scrollbar-color: var(--outline-gray-3) transparent;
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background-color: transparent;
  border-radius: 9999px;
}

:hover::-webkit-scrollbar-thumb {
  background-color: var(--outline-gray-3);
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.fade-in {
  animation: fade-in 0.25s cubic-bezier(0.4, 0, 0.2, 1) both;
}

.dialog-overlay,
.dialog-scroll-container {
  z-index: 50;
}

/* Dropdown/Menu content teleports to <body> without a z-index; lift it above both
   the dialog overlay (z-index: auto, so in-dialog menus like bench actions
   aren't hidden) and the mobile sidebar drawer (z-30, so the sidebar's Bench
   menu stays usable). */
.menu-content {
  z-index: 51;
}

/* Thin scrollbar that's invisible until hovered, for scroll containers where a
   persistent scrollbar would add visual noise (log viewers, data tables). */
.hover-scrollbar {
  scrollbar-color: transparent transparent;
}

.hover-scrollbar:hover {
  scrollbar-color: var(--outline-gray-3) transparent;
}

.hover-scrollbar::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

.hover-scrollbar::-webkit-scrollbar-thumb {
  background-color: transparent;
  border-radius: 9999px;
}

.hover-scrollbar:hover::-webkit-scrollbar-thumb {
  background-color: var(--outline-gray-3);
}

.hover-scrollbar::-webkit-scrollbar-track {
  background: transparent;
}

